#!/usr/bin/env bash
# Builds the Safari extension: Apple's Web Extension wrapper app
# (browser-extension/safari-app, generated by safari-web-extension-converter
# from browser-extension/safari) -> .app -> .dmg, optionally signed with a
# Developer ID and notarized. Runs on macOS with Xcode only; CI and local
# builds on a Mac use this same script.
#
# Usage: scripts/build-safari-extension.sh [output-dir]   (default: artifacts/extensions/safari)
#
# The version comes from browser-extension/safari/manifest.json (kept equal
# to the Chrome and Firefox manifests by release-extension.yml).
#
# Optional environment:
#   MACOS_SIGN_IDENTITY  "Developer ID Application: Name (TEAMID)". Unset: the
#                        build is signed ad hoc and only runs on this Mac with
#                        Safari's "Allow unsigned extensions" developer setting.
#   MACOS_TEAM_ID        Apple team id for the signing identity (CI sets it).
#   NOTARY_KEY_PATH, NOTARY_KEY_ID, NOTARY_ISSUER_ID
#                        App Store Connect API key; with an identity, notarize and staple.
set -euo pipefail

repo_dir="$(cd "$(dirname "$0")/.." && pwd)"
project_dir="$repo_dir/browser-extension/safari-app"
out_dir="${1:-$repo_dir/artifacts/extensions/safari}"
mkdir -p "$out_dir"
out_dir="$(cd "$out_dir" && pwd)"

version="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["version"])' "$repo_dir/browser-extension/safari/manifest.json")"
app_name="Access Workspace Browser Fill"
dmg_path="$out_dir/access-workspace-browser-extension-safari-v${version}.dmg"

work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

# A plain `xcodebuild build` injects the get-task-allow (debugger) entitlement,
# which notarization rejects; CODE_SIGN_INJECT_BASE_ENTITLEMENTS=NO below keeps
# the build a distribution build without going through archive/export.
# Build number: Apple wants CFBundleVersion to increase on every upload; the
# semantic version alone would collide on a rebuild, so append the UTC minute.
build_number="$(date -u +%Y%m%d%H%M)"

echo "Building Safari extension $version (build $build_number)"
sign_args=()
if [ -n "${MACOS_SIGN_IDENTITY:-}" ]; then
  echo "Signing with: $MACOS_SIGN_IDENTITY"
  sign_args=(CODE_SIGN_STYLE=Manual "CODE_SIGN_IDENTITY=$MACOS_SIGN_IDENTITY" "DEVELOPMENT_TEAM=${MACOS_TEAM_ID:-}" OTHER_CODE_SIGN_FLAGS=--timestamp)
else
  echo "MACOS_SIGN_IDENTITY not set: ad-hoc signature (local testing only)"
  sign_args=(CODE_SIGN_STYLE=Manual CODE_SIGN_IDENTITY=- DEVELOPMENT_TEAM= PROVISIONING_PROFILE_SPECIFIER=)
fi
xcodebuild \
  -project "$project_dir/$app_name.xcodeproj" \
  -scheme "$app_name" \
  -configuration Release \
  -derivedDataPath "$work/derived" \
  -destination "generic/platform=macOS" \
  ONLY_ACTIVE_ARCH=NO \
  CODE_SIGN_INJECT_BASE_ENTITLEMENTS=NO \
  "MARKETING_VERSION=$version" \
  "CURRENT_PROJECT_VERSION=$build_number" \
  "${sign_args[@]}" \
  build >"$work/xcodebuild.log" 2>&1 || { tail -n 80 "$work/xcodebuild.log" >&2; exit 1; }

app="$work/derived/Build/Products/Release/$app_name.app"
[ -d "$app" ] || { echo "expected $app after the build" >&2; exit 1; }
codesign --verify --strict --deep --verbose=2 "$app"
# Xcode registers its build product with LaunchServices. Left behind after
# the work directory is deleted, that stale entry shares the bundle id with
# the installed app and can make Safari resolve the extension to a dead path
# and list nothing. Unregister it now, while the path still exists.
lsregister=/System/Library/Frameworks/CoreServices.framework/Versions/A/Frameworks/LaunchServices.framework/Versions/A/Support/lsregister
[ -x "$lsregister" ] && "$lsregister" -u "$app" >/dev/null 2>&1 || true

staging="$work/staging"
mkdir -p "$staging"
cp -R "$app" "$staging/"
ln -s /Applications "$staging/Applications"
rm -f "$dmg_path"
hdiutil create -volname "$app_name" -srcfolder "$staging" -fs HFS+ -format UDZO -ov "$dmg_path" >/dev/null
if [ -n "${MACOS_SIGN_IDENTITY:-}" ]; then
  codesign --force --timestamp --sign "$MACOS_SIGN_IDENTITY" "$dmg_path"
fi

if [ -n "${MACOS_SIGN_IDENTITY:-}" ] && [ -n "${NOTARY_KEY_PATH:-}" ] && [ -n "${NOTARY_KEY_ID:-}" ] && [ -n "${NOTARY_ISSUER_ID:-}" ]; then
  echo "Notarizing (waits for Apple)"
  notary_auth=(--key "$NOTARY_KEY_PATH" --key-id "$NOTARY_KEY_ID" --issuer "$NOTARY_ISSUER_ID")
  result="$(xcrun notarytool submit "$dmg_path" "${notary_auth[@]}" --wait --output-format json)"
  echo "$result"
  status="$(plutil -extract status raw - <<<"$result")"
  if [ "$status" != "Accepted" ]; then
    xcrun notarytool log "$(plutil -extract id raw - <<<"$result")" "${notary_auth[@]}" || true
    echo "Notarization failed: $status" >&2
    exit 1
  fi
  xcrun stapler staple "$dmg_path"
  spctl --assess --type open --context context:primary-signature --verbose=2 "$dmg_path"
else
  echo "Notarization skipped (needs MACOS_SIGN_IDENTITY and the NOTARY_* variables)"
fi

echo "Built $dmg_path"
